"""Local worked example: deterministic checkout contract, Python 3.11+.

No HTTP listener or real identity. Caller-supplied role is a teaching input,
not authentication. Use only fictional item IDs and SQLite in-memory data.
"""
import sqlite3

class Checkout:
    def __init__(self):
        self.db = sqlite3.connect(':memory:')
        self.db.execute('CREATE TABLE items (id TEXT PRIMARY KEY, available INTEGER NOT NULL CHECK(available IN (0,1)))')
        self.db.execute('INSERT INTO items VALUES (?,?)', ('demo-1', 1))
        self.db.commit()
        self.events = []

    def request(self, method, item_id, role='reader'):
        if method not in ('GET', 'POST'):
            return self._reply(405, 'method_not_allowed')
        if role not in ('reader', 'desk'):
            return self._reply(403, 'forbidden')
        if method == 'POST' and role != 'desk':
            return self._reply(403, 'forbidden')
        row = self.db.execute('SELECT available FROM items WHERE id=?', (item_id,)).fetchone()
        if row is None:
            return self._reply(404, 'not_found')
        if method == 'GET':
            return self._reply(200, 'available' if row[0] else 'checked_out')
        # Conditional update enforces the state transition in this local fixture.
        # This single-connection example does not establish multi-client behavior.
        with self.db:
            changed = self.db.execute('UPDATE items SET available=0 WHERE id=? AND available=1', (item_id,)).rowcount
        return self._reply(201, 'checkout_created') if changed else self._reply(409, 'already_checked_out')

    def _reply(self, status, outcome):
        self.events.append({'status': status, 'outcome': outcome})
        return {'status': status, 'outcome': outcome}

    def close(self):
        self.db.close()

"""Worked-example tests. Independent assignment requires additional cases."""
import unittest
from checkout import Checkout

class ContractTests(unittest.TestCase):
    def setUp(self): self.app=Checkout()
    def tearDown(self): self.app.close()
    def test_get_does_not_change_availability(self):
        self.assertEqual(self.app.request('GET','demo-1')['outcome'], 'available')
        self.assertEqual(self.app.request('GET','demo-1')['outcome'], 'available')
    def test_desk_can_checkout_once(self):
        self.assertEqual(self.app.request('POST','demo-1','desk')['status'],201)
        self.assertEqual(self.app.request('POST','demo-1','desk')['status'],409)
    def test_reader_cannot_mutate(self):
        self.assertEqual(self.app.request('POST','demo-1','reader')['status'],403)
        self.assertEqual(self.app.request('GET','demo-1')['outcome'],'available')
    def test_unknown_item(self):
        self.assertEqual(self.app.request('GET','missing')['status'],404)
    def test_parameter_binding_treats_input_as_data(self):
        self.assertEqual(self.app.request('GET',"demo-1' OR 1=1 --")['status'],404)
        self.assertEqual(self.app.request('GET','demo-1')['status'],200)
    def test_log_is_bounded_to_status_and_outcome(self):
        self.app.request('GET','demo-1')
        self.assertEqual(set(self.app.events[0]), {'status','outcome'})

if __name__=='__main__': unittest.main()

"""Fictional whole-GiB capacity example; no disk access or external dependencies."""
def capacity(total, used, reserve):
    if any(type(value) is not int for value in (total, used, reserve)):
        raise TypeError('capacities must be whole-number GiB values')
    if total <= 0:
        raise ValueError('total must be positive')
    if used < 0 or reserve < 0 or used + reserve > total:
        raise ValueError('used and separate reserve must fit within total')
    free_percent = (total - used - reserve) / total * 100
    if free_percent >= 15:
        policy = 'meets'
    else:
        policy = 'below'
    return {'free_percent': free_percent, 'policy': policy}

if __name__ == '__main__':
    result = capacity(256, 180, 12)
    print(f"Usable free: {result['free_percent']:.3f}%; {result['policy']} fixture policy")

import unittest
from capacity import capacity

class CapacityContract(unittest.TestCase):
    def test_example(self):
        self.assertEqual(capacity(256, 180, 12), {'free_percent': 25.0, 'policy': 'meets'})
    def test_below_policy_is_valid(self):
        self.assertEqual(capacity(256, 220, 12), {'free_percent': 9.375, 'policy': 'below'})
    def test_exact_threshold(self):
        self.assertEqual(capacity(200, 160, 10), {'free_percent': 15.0, 'policy': 'meets'})
    def test_full_volume(self):
        self.assertEqual(capacity(100, 90, 10), {'free_percent': 0.0, 'policy': 'below'})
    def test_empty_volume(self):
        self.assertEqual(capacity(100, 0, 0), {'free_percent': 100.0, 'policy': 'meets'})
    def test_zero_total(self):
        with self.assertRaisesRegex(ValueError, 'positive'):capacity(0, 0, 0)
    def test_impossible_capacity(self):
        for values in [(100, -1, 0), (100, 1, -1), (100, 95, 10), (-100, 0, 0)]:
            with self.subTest(values=values),self.assertRaises(ValueError):capacity(*values)
    def test_text_and_fractional_inputs(self):
        for value in ['100', 100.0, None, []]:
            with self.subTest(value=value),self.assertRaises(TypeError):capacity(value, 0, 0)
    def test_boolean_is_not_measurement(self):
        with self.assertRaises(TypeError):capacity(100, True, 0)

if __name__ == '__main__':unittest.main()
